<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,requestKey} from '../api/client'
import {names,date,display,type Attempt,type Family,type TrainingSession,type Render} from '../types'
import TaskProblem from '../components/TaskProblem.vue'
import WorkedExplanation from '../components/WorkedExplanation.vue'
const restoredOffset=ref(0),restoredTotal=ref(0)
const restored=ref<{id:string;family:Family;difficulty:number;created:number;review?:{instructions:string;render:Render;steps:string[];scratchpad:string};reflection:{note?:string}}[]>([])
const route=useRoute(),router=useRouter(),rows=ref<Attempt[]>([]),selected=ref<Attempt|null>(null),filter=ref('all'),family=ref(''),error=ref(''),busy=ref(false),note=ref(''),category=ref(''),saved=ref(''),reportText=ref(''),reportCategory=ref('confusing'),offset=ref(0),total=ref(0)
async function load(){busy.value=true;error.value='';try{if(route.params.id){selected.value=await api<Attempt>('/attempts/'+route.params.id);note.value=selected.value.reflection.note??'';category.value=selected.value.reflection.category??''}else{const r=await api<{items:Attempt[];total:number}>(`/attempts?filter=${filter.value}&family=${family.value}&offset=${offset.value}`);rows.value=r.items;total.value=r.total;const imported=await api<{items:typeof restored.value;total:number}>('/restored?offset='+restoredOffset.value);restored.value=imported.items;restoredTotal.value=imported.total}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function fresh(f:Family){await action(async()=>{const s=await api<TrainingSession>('/sessions','POST',{mode:'focus',family:f},requestKey());await router.push('/train/'+s.id)})}
async function save(){await action(async()=>{await api('/attempts/'+selected.value!.id+'/reflection','PATCH',{note:note.value,category:category.value||null});saved.value='Reflection saved.'})}
async function report(){await action(async()=>{await api('/instances/'+selected.value!.task!.instance_id+'/report','POST',{category:reportCategory.value,note:reportText.value});saved.value='Item report saved. Thank you for making the notebook clearer.';reportText.value=''})}
onMounted(load)
</script>
<template><div class="eyebrow">02 / YOUR REASONING JOURNAL</div><h1>{{selected?'Return to a thought.':'Something to learn from.'}}</h1><p class="lead">Your first answers. The help you used. The reasoning that followed.</p><div v-if="error" class="error" role="alert">{{error}}</div>
 <template v-if="selected"><RouterLink to="/review" class="back-link">← All attempts</RouterLink><section class="panel historical-task"><div class="section-heading"><h2>{{names[selected.family]}}</h2><span>LEVEL {{selected.difficulty}} · {{date(selected.created)}}</span></div><p>{{selected.mode}} · {{selected.assisted?'assisted':'independent'}} · {{selected.correct===null?'feedback pending':selected.correct?'correct':'incorrect'}}</p><div v-if="selected.sealed" class="notice"><h3>Assessment content is sealed.</h3><p>Finish the check, then explicitly release its solutions to review individual items. Exposure will be recorded.</p><RouterLink class="button" :to="'/train/'+selected.session_id">Open assessment →</RouterLink></div><template v-else-if="selected.task"><h3>{{selected.task.instructions}}</h3><TaskProblem :task="selected.task" :model-value="selected.answer??null" locked/><p class="submitted-answer">Your submitted answer: {{display(selected.answer)}}</p><WorkedExplanation v-if="selected.explanation" :explanation="selected.explanation"/><div class="reflection"><label>Reflection<select v-model="category"><option value="">Choose a category</option><option v-for="c in ['missing constraint','untested alternative','wrong rule','execution mistake','unclear instruction','other']" :key="c">{{c}}</option></select></label><label>Your note<textarea v-model="note" maxlength="3000" rows="3"></textarea></label><button @click="save" :disabled="busy">Save reflection</button><p role="status">{{saved}}</p></div><div class="actions"><button class="primary" @click="fresh(selected.family)" :disabled="busy">Try a fresh example →</button><RouterLink class="button" :to="'/discussion/'+selected.id">Discuss this problem ↗</RouterLink></div><details class="report"><summary>Report a confusing or incorrect item</summary><label>Issue category<select v-model="reportCategory"><option>confusing</option><option>incorrect</option><option>accessibility</option><option>other</option></select></label><label>What should we look at?<textarea v-model="reportText" maxlength="1000" rows="2"></textarea></label><button @click="report" :disabled="busy">Save item report</button></details></template></section></template>
 <template v-else><div class="filters"><label>Show<select v-model="filter" @change="offset=0;load()"><option value="all">All attempts</option><option value="mistakes">Independent mistakes</option><option value="assisted">Assisted attempts</option></select></label><label>Family<select v-model="family" @change="offset=0;load()"><option value="">All families</option><option v-for="(name,id) in names" :key="id" :value="id">{{name}}</option></select></label></div><div v-if="!rows.length&&!busy" class="empty-state"><h2>No thoughts on this page yet.</h2><p>Start a session. Every submitted practice problem gets a worked explanation here.</p><RouterLink class="button primary" to="/">Find your first problem →</RouterLink></div><div class="journal-list"><RouterLink v-for="a in rows" :key="a.id" :to="'/review/'+a.id" class="journal-row"><span class="outcome-mark">{{a.sealed?'□':a.correct?'✓':'↺'}}</span><div><h3>{{names[a.family]}}</h3><p>Level {{a.difficulty}} · {{a.mode}} · {{a.assisted?'assisted':'independent'}} {{a.sealed?'· solutions sealed':''}}</p></div><span>{{date(a.created)}} ↗</span></RouterLink></div><div class="actions" v-if="total>30"><button :disabled="offset===0||busy" @click="offset-=30;load()">← Previous</button><span>{{offset+1}}–{{Math.min(offset+30,total)}} / {{total}}</span><button :disabled="offset+30>=total||busy" @click="offset+=30;load()">Next →</button></div><section v-if="restored.length" class="panel"><span class="eyebrow">RESTORED / UNVERIFIED HISTORY</span><h2>Pages brought back.</h2><p class="muted">Imported records never count as canonical attempts or assessment evidence.</p><details v-for="r in restored" :key="r.id"><summary>{{names[r.family]}} · level {{r.difficulty}} · {{date(r.created)}}</summary><p v-if="r.review">{{r.review.instructions}}</p><ol v-if="r.review"><li v-for="(step,i) in r.review.steps" :key="i">{{step}}</li></ol><p v-if="r.reflection.note">Reflection: {{r.reflection.note}}</p><p v-if="r.review?.scratchpad">Scratchpad: {{r.review.scratchpad}}</p></details><div v-if="restoredTotal>30" class="actions"><button :disabled="restoredOffset===0||busy" @click="restoredOffset-=30;load()">← Previous imported pages</button><span>{{restoredOffset+1}}–{{Math.min(restoredOffset+30,restoredTotal)}} / {{restoredTotal}}</span><button :disabled="restoredOffset+30>=restoredTotal||busy" @click="restoredOffset+=30;load()">Next imported pages →</button></div></section></template></template>
